//! src/melee/gm/gmomake15.c: the "Omake 15" movie scene (plays MvOmake15.mth, then returns to
//! the title). No float math. Verified against the C by the TU state oracle
//! (tests/tuo_gmomake15.rs; oracle/tuo).
#![allow(non_snake_case, non_upper_case_globals, static_mut_refs)]

use core::ffi::c_void;
use core::ptr::null_mut;
use melee_types::*;

/// `PAD_MAX_CONTROLLERS` (dolphin/pad.h).
const PAD_MAX_CONTROLLERS: u8 = 4;

pub mod ext {
    //! Callees in TUs that are not ported (TODO stubs, named like the C function) and the globals
    //! the C defines elsewhere. Generated by oracle/tuo/gen_tuo.py; every callee is a settable hook.
    #![allow(non_snake_case, non_upper_case_globals, dead_code)]
    macro_rules! hook {
        ($h:ident, $name:ident, ($($a:ident: $t:ty),*) $(-> $r:ty)?) => {
            pub static mut $h: Option<unsafe extern "C" fn($($t),*) $(-> $r)?> = None;
            pub unsafe extern "C" fn $name($($a: $t),*) $(-> $r)? {
                match $h {
                    Some(f) => f($($a),*),
                    None => panic!(concat!("TODO: ", stringify!($name), " is not ported")),
                }
            }
        };
    }
    /// Like `hook!`, but an unset hook calls an existing verified port.
    macro_rules! hook_or {
        ($h:ident, $name:ident, $port:path, ($($a:ident: $t:ty),*) $(-> $r:ty)?) => {
            pub static mut $h: Option<unsafe extern "C" fn($($t),*) $(-> $r)?> = None;
            pub unsafe extern "C" fn $name($($a: $t),*) $(-> $r)? {
                match $h {
                    Some(f) => f($($a),*),
                    None => $port($($a),*),
                }
            }
        };
    }
    // ---- callee hooks ----
    hook!(H_GObj_Create, GObj_Create, (a0: u16, a1: u8, a2: u8) -> *mut melee_types::HSD_GObj);
    hook!(H_gm_801A9DD0, gm_801A9DD0, (a0: *mut melee_types::HSD_GObj, a1: u16, a2: u16, a3: i32, a4: i32));
    hook!(H_HSD_GObjObject_80390A70, HSD_GObjObject_80390A70, (a0: *mut melee_types::HSD_GObj, a1: u8, a2: *mut core::ffi::c_void));
    hook!(H_GObj_SetupGXLink, GObj_SetupGXLink, (a0: *mut melee_types::HSD_GObj, a1: Option<unsafe extern "C" fn(*mut melee_types::HSD_GObj, i32)>, a2: u8, a3: u32));
    hook!(H_lbMthp_8001F67C, lbMthp_8001F67C, (a0: *mut melee_types::HSD_GObj, a1: i32));
    hook!(H_lbMthp_8001F624, lbMthp_8001F624, (a0: *mut melee_types::HSD_GObj, a1: i32, a2: i32) -> *mut melee_types::HSD_SObj);
    hook!(H_lbAudioAx_80023F28, lbAudioAx_80023F28, (a0: i32) -> i32);
    hook!(H_lbAudioAx_80024E50, lbAudioAx_80024E50, (a0: i32));
    hook!(H_lbMthp_8001F410, lbMthp_8001F410, (a0: *const i8, a1: *mut u32, a2: *mut core::ffi::c_void, a3: u32, a4: i32));
    hook!(H_fn_801AA0E8, fn_801AA0E8, ());
    hook!(H_lbMthp_8001F578, lbMthp_8001F578, ());
    hook!(H_lbMthp_8001F5C4, lbMthp_8001F5C4, () -> i32);
    hook!(H_lbMthp_8001F604, lbMthp_8001F604, () -> i32);
    hook!(H_gm_GetButtonsTriggered, gm_GetButtonsTriggered, (a0: u8) -> u64);
    hook!(H_lbAudioAx_800236DC, lbAudioAx_800236DC, () -> i32);
    hook!(H_gm_801A4B74, gm_801A4B74, ());
    hook!(H_gm_801A4B60, gm_801A4B60, ());
    hook!(H_gmMainLib_8015DB0C, gmMainLib_8015DB0C, (a0: u8));
    hook!(H_gm_SetPendingGameMode, gm_SetPendingGameMode, (a0: u8));
    hook!(H_gm_SetNewGameModePending, gm_SetNewGameModePending, ());
    hook!(H_lbAudioAx_80024030, lbAudioAx_80024030, (a0: i32));
    // ---- extern globals ----
    pub static mut HSD_SObjLib_804D7960: u8 = unsafe { core::mem::zeroed() };
    pub static mut gm_804D6724: Option<unsafe extern "C" fn()> = unsafe { core::mem::zeroed() };
    pub static mut gmMainLib_8046B0F0: melee_types::gmMainLib_8046B0F0_t = unsafe { core::mem::zeroed() };
}

/// `static HSD_GObj* gm_804D6858`
pub static mut gm_804D6858: *mut HSD_GObj = null_mut();

pub unsafe extern "C" fn gm_Scene_Omake15_OnEnter(_unused: *mut c_void) {
    let mut gobj = ext::GObj_Create(0x13, 0x14, 0);
    ext::gm_801A9DD0(gobj, 0x280, 0x1E0, 8, 0);
    (*gobj).gxlink_prios = 0x800;

    gobj = ext::GObj_Create(0xE, 0xF, 0);
    gm_804D6858 = gobj;
    ext::HSD_GObjObject_80390A70(gobj, ext::HSD_SObjLib_804D7960, null_mut());
    ext::GObj_SetupGXLink(gobj, Some(ext::lbMthp_8001F67C), 0xB, 0);
    let sobj = ext::lbMthp_8001F624(gobj, 0x1C0, 0x150);
    (*sobj).x10 = 96.0;
    (*sobj).x14 = 72.0;
    ext::lbAudioAx_80023F28(0x52);
    ext::lbAudioAx_80024E50(1);
    ext::lbMthp_8001F410(c"MvOmake15.mth".as_ptr(), null_mut(), null_mut(), 0, 0);
    ext::lbAudioAx_80024E50(0);
    ext::gm_804D6724 = Some(ext::fn_801AA0E8);
}

/// `sfxForward()` (inline, mn/inlines.h).
#[inline(always)]
unsafe fn sfxForward() {
    ext::lbAudioAx_80024030(1);
}

pub unsafe extern "C" fn gm_Scene_Omake15_OnFrame() {
    let mut var_r31 = false;

    ext::lbMthp_8001F578();
    ext::lbMthp_8001F5C4();
    if ext::gmMainLib_8046B0F0.xC != 0 && ext::lbMthp_8001F604() == 0 {
        var_r31 = true;
    }
    if ext::lbMthp_8001F604() != 0
        || (ext::gm_GetButtonsTriggered(PAD_MAX_CONTROLLERS) & (HSD_PAD_START | HSD_PAD_A) as u64) != 0
        || var_r31
    {
        ext::lbAudioAx_800236DC();
        if var_r31 {
            ext::gm_801A4B74();
        } else {
            ext::gm_801A4B60();
        }
        ext::gmMainLib_8015DB0C(0);
        if (ext::gm_GetButtonsTriggered(PAD_MAX_CONTROLLERS) & (HSD_PAD_START | HSD_PAD_A) as u64) != 0
            || var_r31
        {
            if !var_r31 {
                sfxForward();
            }
            ext::gm_SetPendingGameMode(GM_TITLE as u8);
            ext::gm_SetNewGameModePending();
        }
    }
}
